#include "main.h"
#include <stdio.h>
// VCC→3V3, GND→GND, 장치 TX→PA10(D2, USART1 RX), 장치 RX→PA9(D8, USART1 TX), 9600 baud · 하단 직렬 모니터 탭에서 외부 UART 장치 → USART1 선택 · PA2/PA3(D1/D0)은 보드 기본 상태(SB62/SB63 열림)에서 ST-LINK 가상 COM 전용
uint8_t rx[1];
volatile uint8_t echo[64];
volatile uint32_t echoHead = 0, echoTail = 0;

/* Copy this main.c into a CubeIDE STM32F446RE project with matching
 * pin / peripheral / NVIC settings and Cube-generated IRQ / MSP files.
 * Clock: HSI PLL, APB1 timer clock = 84000000 Hz.
 * printf: SWV ITM port 0 (enable SWV in the debugger). UART uses its pins.
 * With newlib-nano, enable -u _printf_float for floating-point printf. */

UART_HandleTypeDef huart1;

void SystemClock_Config(void);
void Error_Handler(void);
static void MX_GPIO_Init(void);
static void MX_USART1_UART_Init(void);

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_USART1_UART_Init();
    /* USER CODE BEGIN 2 */
    uint8_t message[] = "HAL UART ready\r\n";
    HAL_UART_Transmit(&huart1, message, sizeof(message)-1, 100);
    HAL_UART_Receive_IT(&huart1, rx, 1);
    /* USER CODE END 2 */
    while (1) {
        /* USER CODE BEGIN 3 */
        while (echoTail != echoHead) {
            uint8_t c = echo[echoTail % 64];
            echoTail++;
            HAL_UART_Transmit(&huart1, &c, 1, 10);
        }
        HAL_Delay(1);
        /* USER CODE END 3 */
    }
}

